#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,k;scanf("%d %d",&n,&k);vector<int>a(n);
for(int i=0;i<n;++i)scanf("%d",&a[i]);
int lo=0,hi=n;
while(lo<hi){int mid=lo+(hi-lo)/2;
if(a[mid]-mid-1<k)lo=mid+1;else hi=mid;}
printf("%d\n",lo+k);return 0;}

